<div class="actions"><a class="btn primary" href="<?=e(base_url('oauth/google.php?provider=youtube'))?>">+ Connect YouTube Channel</a></div>
<div class="grid cards"><?php foreach($channels as $c):?><div class="card"><h2><?=e($c['channel_name'])?></h2><div class="muted"><?=e($c['channel_id'])?></div><p>Status: <span class="badge"><?=e($c['status'])?></span></p>
<form method="post" class="stack"><input type="hidden" name="_csrf" value="<?=e($security->csrf())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e((string)$c['id'])?>"><label>Channel name<input name="channel_name" value="<?=e($c['channel_name'])?>" required></label><label>Title prefix<input name="prefix" value="<?=e($c['default_title_prefix'])?>"></label><label>Title suffix<input name="suffix" value="<?=e($c['default_title_suffix'])?>"></label><label>Description<textarea name="description" rows="5"><?=e($c['default_description'])?></textarea></label><small>Placeholders: {TITLE}, {CHANNEL_NAME}, {DATE}</small><label>Tags<input name="tags" value="<?=e(implode(', ',json_decode($c['default_tags_json']??'[]',true)?:[]))?>"></label><label>Hashtags<input name="hashtags" value="<?=e(implode(', ',json_decode($c['default_hashtags_json']??'[]',true)?:[]))?>"></label><label>Category ID<input name="category_id" value="<?=e($c['default_category_id'])?>"></label><label>Timezone<input name="timezone" value="<?=e($c['default_timezone'])?>"></label><label>Privacy<select name="privacy_status"><?php foreach(['private','public','unlisted'] as $p):?><option value="<?=$p?>" <?=$c['default_privacy_status']===$p?'selected':''?>><?=e($p)?></option><?php endforeach;?></select></label><label><input type="checkbox" name="made_for_kids" value="1" <?=$c['default_made_for_kids']?'checked':''?>> Made for kids</label><button class="btn primary">Save defaults</button></form>
<div class="row"><form method="post"><input type="hidden" name="_csrf" value="<?=e($security->csrf())?>"><input type="hidden" name="action" value="test"><input type="hidden" name="id" value="<?=e((string)$c['id'])?>"><button class="btn">Test connection</button></form><form method="post"><input type="hidden" name="_csrf" value="<?=e($security->csrf())?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="id" value="<?=e((string)$c['id'])?>"><button class="btn danger">Disable</button></form><a class="btn" href="<?=e(base_url('oauth/google.php?provider=youtube'))?>">Reconnect</a></div></div><?php endforeach;?></div>
